using System;
using System.Drawing;
using System.IO;
using System.Runtime.InteropServices;
using System.Windows.Forms;
internal static class SelfTest {
 [DllImport("user32.dll")] static extern IntPtr WindowFromPoint(Native.Point p);
 [DllImport("user32.dll")] static extern IntPtr SendMessage(IntPtr window,int message,IntPtr w,IntPtr l);
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);lines+= "PASS: "+name+Environment.NewLine;}
 static string lines="";
 internal static int Run(){string temp=Path.Combine(Path.GetTempPath(),"CornerPet-"+Guid.NewGuid()+".gif");try{
  int backgroundActions=0,callbackThread=0,uiThread=System.Threading.Thread.CurrentThread.ManagedThreadId;using(var nativeKeys=new GlobalShortcuts(id=>{backgroundActions++;callbackThread=System.Threading.Thread.CurrentThread.ManagedThreadId;})){Check(nativeKeys.Backend=="shared-keyboard-hook"&&nativeKeys.ModeReady&&nativeKeys.MonitorReady,"native global keyboard hook installs successfully: "+nativeKeys.Failure);nativeKeys.ProcessKey((int)Keys.F7,0x100);System.Threading.Thread.Sleep(50);var deadline=DateTime.UtcNow.AddSeconds(1);while(backgroundActions==0&&DateTime.UtcNow<deadline){Application.DoEvents();System.Threading.Thread.Sleep(1);}Check(backgroundActions==1,"background hook queues actions while UI is busy");Check(callbackThread==uiThread,"background shortcut is marshalled to UI thread");nativeKeys.ProcessKey((int)Keys.F7,0x101);}
  int keyActions=0,lastKey=0;using(var keys=new GlobalShortcuts(id=>{keyActions++;lastKey=id;},false)){Check(keys.ProcessKey((int)Keys.F7,0x100),"F7 keyboard event is handled");Application.DoEvents();Check(keyActions==1&&lastKey==1,"F7 dispatch reaches dedicated native message window");for(int k=0;k<20;k++)keys.ProcessKey((int)Keys.F7,0x100);Application.DoEvents();Check(keyActions==1,"holding F7 does not toggle repeatedly");keys.ProcessKey((int)Keys.F7,0x101);keys.ProcessKey((int)Keys.F7,0x100);Application.DoEvents();Check(keyActions==2,"F7 works again after key release");keys.ProcessKey((int)Keys.F7,0x101);keys.ProcessKey((int)Keys.F8,0x100);Application.DoEvents();Check(keyActions==3&&lastKey==2,"F8 keyboard event reaches display action");keys.ProcessKey((int)Keys.F8,0x101);Check(!keys.ProcessKey((int)Keys.A,0x100),"unrelated keys are not intercepted");}
  int observed=0,forwarded=0;using(var sharedKeys=new GlobalShortcuts(id=>observed++,false)){IntPtr packet=Marshal.AllocHGlobal(4);try{GlobalShortcuts.ForwardProc next=(h,c,m,d)=>{forwarded++;return new IntPtr(917);};foreach(int vk in new[]{(int)Keys.F7,(int)Keys.F8}){Marshal.WriteInt32(packet,vk);Check(sharedKeys.ObserveAndForward(0,new IntPtr(0x100),packet,next)==new IntPtr(917),"shared F"+(vk-(int)Keys.F1+1)+" key-down forwards to next hook");sharedKeys.ObserveAndForward(0,new IntPtr(0x100),packet,next);Check(sharedKeys.ObserveAndForward(0,new IntPtr(0x101),packet,next)==new IntPtr(917),"shared key-up forwards to next hook");}Application.DoEvents();Check(observed==2&&forwarded==6,"each app can receive both shared keys while our repeats remain suppressed");Check(sharedKeys.ObserveAndForward(-1,IntPtr.Zero,IntPtr.Zero,next)==new IntPtr(917)&&forwarded==7,"negative hook codes forward without inspecting keyboard data");}finally{Marshal.FreeHGlobal(packet);}}
  var displays=new[]{new DisplayInfo{Name="main",Primary=true,Work=new Rectangle(0,0,1920,1040)},new DisplayInfo{Name="secondary",Work=new Rectangle(-1280,0,1280,984)},new DisplayInfo{Name="third",Work=new Rectangle(1920,0,1600,900)}};
  Check(ScreenPlacement.Target("main",null,displays)==1,"F8 primary goes to secondary");Check(ScreenPlacement.Target("secondary",null,displays)==0,"F8 secondary returns to primary");Check(ScreenPlacement.Target("third",null,displays)==0,"F8 any non-primary display returns to primary");Check(ScreenPlacement.Target("main","third",displays)==2,"F8 remembers the previously used secondary");Check(ScreenPlacement.Target("main",null,new[]{displays[0]})==-1,"F8 is a no-op with one display");
  var mapped=ScreenPlacement.Map(new Rectangle(1720,880,200,160),displays[0].Work,displays[1].Work);Check(mapped==new Point(-200,824),"monitor mapping preserves bottom-right placement with negative coordinates");var bounded=ScreenPlacement.Map(new Rectangle(-9000,-9000,200,160),displays[0].Work,displays[1].Work);Check(displays[1].Work.Contains(new Rectangle(bounded,new Size(200,160))),"monitor mapping clamps to target work area");
  // Two opaque 1 x 1 GIF frames, each delayed 100 ms.
  byte[] fixture=new byte[]{71,73,70,56,57,97,1,0,1,0,128,0,0,255,0,0,0,255,0,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,68,1,0,33,249,4,0,10,0,0,0,44,0,0,0,0,1,0,1,0,0,2,2,76,1,0,59};File.WriteAllBytes(temp,fixture);
  using(var under=new Form{TopMost=true,StartPosition=FormStartPosition.Manual,Bounds=new Rectangle(50,50,400,400)})using(var pet=new Pet(new Preferences{X=100,Y=100,Width=160},true)){
   under.Show();pet.Show();Application.DoEvents();under.Hide();under.Show();pet.BringToFront();Check(!pet.HasAsset&&!pet.Animating&&pet.BufferBytes==0&&pet.FrameCount==0,"empty startup has no built-in art, timer or pixel buffer");pet.LoadImage(temp);Application.DoEvents();Check(pet.FrameCount==2,"decode animated GIF frames");File.Delete(temp);Check(!File.Exists(temp),"import does not lock original file");
   SendMessage(pet.Handle,0x312,new IntPtr(1),IntPtr.Zero);Check(pet.Game,"F7 hotkey message enables game mode");SendMessage(pet.Handle,0x312,new IntPtr(1),IntPtr.Zero);Check(!pet.Game,"F7 hotkey message restores normal mode");
   var point=new Native.Point(pet.Left+80,pet.Top+80);pet.SetGame(false);Application.DoEvents();Check(WindowFromPoint(point)==pet.Handle,"normal mode receives mouse hit");pet.SetGame(true);Application.DoEvents();Check(WindowFromPoint(point)==under.Handle,"game mode passes mouse hit to underlying window; actual="+WindowFromPoint(point)+" expected="+under.Handle+" pet="+pet.Handle+" point="+point.X+","+point.Y);pet.SetGame(false);Check((Native.GetWindowLong(pet.Handle,-20)&0x20)==0,"normal mode restores input");
   var before=ScreenshotPixel(pet);var until=DateTime.UtcNow.AddMilliseconds(120);while(DateTime.UtcNow<until)Application.DoEvents();var after=ScreenshotPixel(pet);Check(before.ToArgb()!=after.ToArgb(),"GIF animation advances and renders");
   try{pet.LoadImage("missing-file.gif");throw new Exception("invalid image accepted");}catch(FileNotFoundException){}Check(pet.FrameCount==2,"failed import preserves active pet");
   int surfaces=RenderSurface.Created;int gdi=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);for(int n=0;n<3000;n++)pet.Draw();Check(RenderSurface.Created==surfaces&&RenderSurface.Alive==1,"3000 redraws reuse one DIB surface");Check(GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0)<=gdi+2,"3000 redraws do not grow GDI handles");
   pet.Hide();int draws=pet.DrawCount;Check(!pet.Animating&&pet.BufferBytes==0&&!pet.DecoderLoaded&&RenderSurface.Alive==0,"hidden pet stops timer and releases renderer and decoder");pet.Draw();Check(pet.DrawCount==draws,"hidden pet does not render");pet.Show();Check(pet.Animating&&pet.DecoderLoaded&&RenderSurface.Alive==1,"show resumes from private snapshot after original was deleted");
   pet.ResizePet(240);Check(pet.Width==240&&pet.Height==240,"resize preserves aspect ratio");Check(pet.BufferBytes==240L*240*4&&RenderSurface.Alive==1,"resize retains only one display-sized surface");pet.Corner(true,true);Check(Screen.FromRectangle(pet.Bounds).WorkingArea.Contains(pet.Bounds),"corner placement stays in working area");
   using(var png=new Bitmap(16,8)){using(var graphics=Graphics.FromImage(png))graphics.Clear(Color.FromArgb(128,255,0,0));png.Save(temp,System.Drawing.Imaging.ImageFormat.Png);}pet.LoadImage(temp);Check(pet.FrameCount==1&&!pet.Animating,"static image has no animation timer");
   under.BackColor=Color.White;pet.Location=new Point(100,100);pet.Draw();var settle=DateTime.UtcNow.AddMilliseconds(80);while(DateTime.UtcNow<settle)Application.DoEvents();var alpha=pet.RenderPixel(pet.Width/2,pet.Height/2);Check(Math.Abs(alpha.A-128)<=1&&alpha.R>=250&&alpha.G<=2&&alpha.B<=2,"reused DIB preserves alpha and source colors independent of desktop occlusion");
   string snapshot;using(var asset=ImageAsset.Open(temp)){snapshot=asset.SnapshotPath;Check(File.Exists(snapshot),"private snapshot exists while asset is open");}Check(!File.Exists(snapshot),"asset disposal removes private disk snapshot");File.Delete(temp);
   using(var warmPanel=new PanelWindow(pet)){warmPanel.Show();Application.DoEvents();warmPanel.Close();}int panelGdi=GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0);for(int n=0;n<20;n++){using(var panel=new PanelWindow(pet)){panel.Show();Application.DoEvents();panel.Close();}}Check(GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0)<=panelGdi+3,"reopening control panel releases GDI resources; before="+panelGdi+" after="+GetGuiResources(System.Diagnostics.Process.GetCurrentProcess().Handle,0));
   string initialScreen=Screen.FromRectangle(pet.Bounds).DeviceName;SendMessage(pet.Handle,0x312,new IntPtr(2),IntPtr.Zero);string movedScreen=Screen.FromRectangle(pet.Bounds).DeviceName;Check(Screen.AllScreens.Length<2?movedScreen==initialScreen:movedScreen!=initialScreen,"F8 message switches attached display or safely stays with one display");SendMessage(pet.Handle,0x312,new IntPtr(2),IntPtr.Zero);Check(Screen.FromRectangle(pet.Bounds).DeviceName==initialScreen,"second F8 message returns to starting display");
   pet.ClearAsset();Check(!pet.HasAsset&&pet.FrameCount==0&&!pet.Animating&&pet.BufferBytes==0&&pet.State.ImagePath=="","clearing asset leaves an empty, idle pet");pet.Close();Check(RenderSurface.Alive==0,"close releases render surface");under.Close();
  }
  File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),lines);return 0;
 }catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"test-results.txt"),lines+"FAIL: "+ex);return 1;}finally{if(File.Exists(temp))File.Delete(temp);}}
 static Color ScreenshotPixel(Pet p){using(var b=new Bitmap(1,1)){using(var g=Graphics.FromImage(b))g.CopyFromScreen(p.Left+p.Width/2,p.Top+p.Height/2,0,0,new Size(1,1));return b.GetPixel(0,0);}}
 [DllImport("user32.dll")] static extern int GetGuiResources(IntPtr process,int flags);
}
